// Generated by AI (UnitTest MCP)
import { readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

const extensionRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const manifest = JSON.parse(readFileSync(join(extensionRoot, "package.json"), "utf8"));

const groups: { title: string; properties: Record<string, unknown> }[] =
  manifest.contributes.configuration;

const declared = groups.flatMap((group) => Object.keys(group.properties));

const sourceFiles = (dir: string): string[] =>
  readdirSync(dir).flatMap((entry) => {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) return sourceFiles(full);
    return entry.endsWith(".ts") && !entry.endsWith(".test.ts") ? [full] : [];
  });

/**
 * The call shapes a settings read can take. Both must be scanned.
 *
 * The extension reads settings two ways: through a `config` variable held
 * across several reads, and inline off `getConfiguration("mindleak")` for a
 * one-off. Matching only the first left `captureCommits` and `snapshotLimit`
 * invisible — 16 of 18 reads were checked and two were not, so the guard could
 * not have caught the very mistake it exists to catch, had either been
 * undeclared.
 */
const SETTING_READ_PATTERNS = [
  /config\.get(?:<[^>]+>)?\(\s*"([a-zA-Z.]+)"/g,
  /getConfiguration\(\s*"mindleak"\s*\)\s*\.get(?:<[^>]+>)?\(\s*"([a-zA-Z.]+)"/g,
];

/** Every setting id the extension actually reads, by any call shape. */
const readByCode = () => {
  const found = new Set<string>();
  for (const file of sourceFiles(join(extensionRoot, "src"))) {
    const text = readFileSync(file, "utf8");
    for (const pattern of SETTING_READ_PATTERNS) {
      for (const match of text.matchAll(pattern)) {
        found.add(`mindleak.${match[1]}`);
      }
    }
  }
  return [...found];
};

describe("settings surface", () => {
  /**
   * Eighteen settings arrived as one flat list, so "where is the server binary"
   * sat beside "how many characters of terminal output to retain" with nothing
   * to say which a first-time user needs. Grouping is presentation only — the
   * ids are untouched, so no existing user configuration moves.
   */
  it("puts every setting in exactly one group", () => {
    const seen = new Map<string, number>();
    for (const key of declared) seen.set(key, (seen.get(key) ?? 0) + 1);

    const duplicated = [...seen].filter(([, count]) => count > 1).map(([key]) => key);

    expect(duplicated).toEqual([]);
  });

  it("declares no empty group", () => {
    const empty = groups.filter((group) => Object.keys(group.properties).length === 0);

    expect(empty.map((group) => group.title)).toEqual([]);
  });

  it("gives every group a title so the UI can section it", () => {
    const untitled = groups.filter((group) => !group.title?.trim());

    expect(untitled.length).toBe(0);
  });

  /**
   * The bug this actually prevents: a setting read by the code but never
   * declared in the manifest silently returns the inline fallback, so it cannot
   * be discovered in the settings UI and never appears to do anything when a
   * user sets it in JSON. Grouping made that easy to introduce, because a new
   * setting must now be added to a group rather than to one obvious list.
   */
  it("declares every setting the code reads", () => {
    const undeclared = readByCode().filter((key) => !declared.includes(key));

    expect(undeclared).toEqual([]);
  });

  /**
   * Guards the guard. A scrape that matches nothing would pass vacuously, and a
   * scrape that matches *most* things is worse: it reports green while a whole
   * call shape goes unchecked. The original floor of "more than 5" was satisfied
   * by 16 of 18 reads, which is exactly how the inline shape stayed invisible.
   * Naming one read of each shape is what actually holds the blind spot closed.
   */
  it("sees both call shapes, not just reads through a config variable", () => {
    const read = readByCode();

    // Held in a `config` variable.
    expect(read).toContain("mindleak.serverPath");
    // Read inline off getConfiguration("mindleak").
    expect(read).toContain("mindleak.captureCommits");
    expect(read).toContain("mindleak.snapshotLimit");
  });

  it("still finds the settings the extension reads", () => {
    expect(readByCode().length).toBeGreaterThan(5);
  });

  /**
   * Regression: the MCP client request timeout was a flat 30000ms, exactly equal
   * to the server-side model budget (MINDLEAK_HTTP_TIMEOUT_MS default). A
   * model-backed tool call — design-promotion planning, goal decomposition —
   * that ran near that budget was abandoned by the client at the same instant
   * the server was still waiting, so the deterministic fallback never reached
   * the user and promotion surfaced only `tools/call timed out after 30000ms`.
   * The configurable client budget must outlast the model budget, so its default
   * is required to exceed 30000ms.
   */
  it("gives the MCP request timeout headroom over the model budget", () => {
    const MODEL_BUDGET_MS = 30000;
    const timeout = groups
      .flatMap((group) => Object.entries(group.properties))
      .find(([key]) => key === "mindleak.requestTimeoutMs")?.[1] as
      { default?: number; minimum?: number } | undefined;

    expect(timeout, "mindleak.requestTimeoutMs must be declared").toBeDefined();
    expect(timeout!.default).toBeGreaterThan(MODEL_BUDGET_MS);
    expect(timeout!.minimum ?? 0).toBeGreaterThan(0);
  });
});
